import React, { useState, useEffect, useCallback } from 'react';
import { Box, Avatar, Typography, Tooltip } from '@mui/material';
import DataTable from '../../../components/DataTable';
import ConfirmationModal from '../../../components/ConfirmationModal';
import { toast } from 'react-hot-toast';
import { Verified } from '@mui/icons-material';
import { useSelector } from 'react-redux';
import AvatarView from '../../../components/AvatarView';
import { mapDeletedUserExport } from '../../../utils/exportMappers';
import { extractExportList, performExport } from '../../../utils/exportHelpers';
import dayjs from 'dayjs';

const BASE_URL = process.env.REACT_APP_API_BASE_URL;

const DeletedUsers = () => {
  const [deletedUsers, setDeletedUsers] = useState([]);
  const [userToDelete, setUserToDelete] = useState(null);
  const [openDeleteModal, setOpenDeleteModal] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [page, setPage]               = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(5);
  const [totalCount, setTotalCount]   = useState(0);
  const [searchTerm, setSearchTerm]   = useState('');
  const [orderBy, setOrderBy]         = useState('deleted_at');
  const [order, setOrder]             = useState('desc');
  const [isExporting, setIsExporting] = useState(false);

  const token = useSelector((state) => state.auth.token);

  const fetchDeletedUsers = useCallback(async (apiPage, limit) => {
    if (!token) return;
    setIsLoading(true);
    try {
      const params = {
        page: apiPage,
        limit: limit,
        sort_by: orderBy,
        sort_order: order,
      };

      if (searchTerm) {
        params.q = searchTerm;
      }

      const queryParams = new URLSearchParams(params);

      const res = await fetch(`${BASE_URL}/users/deleted?${queryParams.toString()}`, {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
      });
      const json = await res.json();
      if (!res.ok || json.error) {
        toast.error(json.message || 'Failed to fetch deleted users');
        return;
      }
      setDeletedUsers(json.data?.users || []);
      setTotalCount(json.data?.pagination?.total || 0);
    } catch (err) {
      console.error('Error fetching deleted users:', err);
      toast.error('Something went wrong while fetching deleted users');
    } finally {
      setIsLoading(false);
    }
  }, [token, orderBy, order, searchTerm]);

  useEffect(() => {
    if (token) {
      fetchDeletedUsers(page + 1, rowsPerPage);
    }
  }, [page, rowsPerPage, fetchDeletedUsers, token]);

  const handleSortChange = (property) => {
    const isAsc = orderBy === property && order === 'asc';
    setOrder(isAsc ? 'desc' : 'asc');
    setOrderBy(property);
    setPage(0);
  };

  // ── Delete Handlers ────────────────────────────────────────────────────────
  const handleDeleteUser = (user) => {
    setUserToDelete(user);
    setOpenDeleteModal(true);
  };

  const handleConfirmDelete = async () => {
    if (!userToDelete || !token) return;
    const toastId = toast.loading('Deleting user...');
    try {
      const res = await fetch(`${BASE_URL}/users/${userToDelete.id}/hard`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
      });
      const json = await res.json();
      if (!res.ok || json.error) {
        throw new Error(json.message || 'Failed to delete user');
      }
      toast.success('User deleted successfully', { id: toastId });
      fetchDeletedUsers(page + 1, rowsPerPage);
    } catch (err) {
      console.error('Delete error:', err);
      toast.error(err.message || 'Something went wrong while deleting user', { id: toastId });
    } finally {
      setOpenDeleteModal(false);
      setUserToDelete(null);
    }
  };

  const COLUMNS = [
    {
      id: 'name',
      label: 'Name',
      sortable: true,
      render: (row) => (
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
          <AvatarView
            user={row}
            alt={row.name}
            previewTitle={row.name}
            sx={{
              width: 34,
              height: 34,
              bgcolor: 'rgba(255,80,80,0.2)',
              color: '#FF5050',
              fontSize: '0.8rem',
              fontWeight: 700,
              fontFamily: "'Montserrat', sans-serif",
            }}
          >
            {row.name ? row.name.split(' ').map(n => n[0]).join('').slice(0, 2).toUpperCase() : 'U'}
          </AvatarView>
          <Box>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
              <Typography sx={{ color: '#FFFFFF', fontSize: '0.875rem', fontFamily: "'Montserrat', sans-serif", fontWeight: 500 }}>
                {row.name || 'Unknown'}
              </Typography>
              {row.is_verified && (
                <Tooltip title="Verified User">
                  <Verified sx={{ color: '#1D9BF0', fontSize: '1rem' }} />
                </Tooltip>
              )}
            </Box>
            <Typography sx={{ color: '#8B8D97', fontSize: '0.75rem', fontFamily: "'Montserrat', sans-serif" }}>
              {row.email}
            </Typography>
          </Box>
        </Box>
      ),
    },

    { 
      id: 'created_at', 
      label: 'Joined',
      sortable: true,
      render: (row) => (
        <Typography sx={{ color: '#8B8D97', fontSize: '0.875rem', fontFamily: "'Montserrat', sans-serif" }}>
          {row.created_at ? new Date(row.created_at).toLocaleDateString('en-GB') : '-'}
        </Typography>
      )
    },

    { 
      id: 'deleted_at', 
      label: 'Deleted Date',
      sortable: true,
      render: (row) => (
        <Typography sx={{ color: '#FF5050', fontSize: '0.875rem', fontFamily: "'Montserrat', sans-serif", fontWeight: 600 }}>
          {row.deleted_at ? new Date(row.deleted_at).toLocaleDateString('en-GB') : '-'}
        </Typography>
      )
    },
  ];

  // ── CSV Export ────────────────────────────────────────────────────────────
  const handleExportDeletedUsers = useCallback(async (dates, format) => {
    if (!token) return;
    const toastId = toast.loading(`Exporting deleted users as ${format.toUpperCase()}...`);
    setIsExporting(true);
    try {
      const params = {
        sort_by: orderBy,
        sort_order: order,
        not_pagination: 'true',
        start_date: dates.startDate.format('YYYY-MM-DD'),
        end_date: dates.endDate.format('YYYY-MM-DD'),
      };

      if (searchTerm) {
        params.q = searchTerm;
      }

      const queryParams = new URLSearchParams(params);

      const res = await fetch(`${BASE_URL}/users/deleted?${queryParams.toString()}`, {
        method: 'GET',
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
      });

      const json = await res.json();
      if (!res.ok || json.error) {
        throw new Error(json.message || 'Failed to fetch users for export');
      }

      // Robust extraction
      const items = extractExportList(json, 'users');
      const filename = `Deleted_Users_${dates.startDate.format('YYYYMMDD')}_to_${dates.endDate.format('YYYYMMDD')}`;

      await performExport({
        items,
        mapper: mapDeletedUserExport,
        format,
        filename,
        sheetName: 'Deleted Users',
        entityName: 'deleted users',
        toastId,
      });
    } catch (err) {
      console.error('Export error:', err);
      toast.error(err.message || 'Something went wrong while exporting', { id: toastId });
    } finally {
      setIsExporting(false);
    }
  }, [token, searchTerm, orderBy, order]);

  return (
    <Box sx={{ p: { xs: 1, md: 2 } }}>
      <DataTable
        title="Deleted Users"
        columns={COLUMNS}
        data={deletedUsers}
        isLoading={isLoading}
        searchTerm={searchTerm}
        onSearchChange={(val) => {
          setSearchTerm(val);
          setPage(0);
        }}
        orderBy={orderBy}
        order={order}
        onSortChange={handleSortChange}
        onExport={handleExportDeletedUsers}
        isExporting={isExporting}
        pagination={{
          page,
          rowsPerPage,
          totalCount: totalCount,
          onPageChange: (_, newPage) => setPage(newPage),
          onRowsPerPageChange: (e) => { 
            setRowsPerPage(parseInt(e.target.value, 10)); 
            setPage(0); 
          },
        }}
        onDeleteClick={handleDeleteUser}
        emptyTitle="No deleted users"
        emptyMessage="There are currently no deleted users in the system."
      />
      <ConfirmationModal
        open={openDeleteModal}
        onClose={() => setOpenDeleteModal(false)}
        onConfirm={handleConfirmDelete}
        title="Delete User?"
        message={`Are you sure you want to delete ${userToDelete?.name}? This action cannot be undone.`}
        confirmText="Delete"
        confirmColor="error"
      />
    </Box>
  );
};

export default DeletedUsers;
