import React from 'react';
import { 
    Button, 
    Stack, 
    Typography, 
    Box, 
    CircularProgress, 
    alpha 
} from '@mui/material';
import { WarningAmber as WarningIcon } from '@mui/icons-material';
import BaseModal from './BaseModal';

const ICON_COLORS = {
    primary: '#4CC66E',
    warning: '#FFCC00',
    error: '#FF5050',
};

const ConfirmationModal = ({
    open,
    onClose,
    onConfirm,
    title = 'Confirm Action',
    message = 'Are you sure you want to proceed?',
    confirmText = 'Confirm',
    cancelText = 'Cancel',
    confirmColor = 'primary',
    loading = false,
    icon: Icon = WarningIcon,
    maxWidth = 'xs',
    iconColor,
}) => {
    const accentColor = iconColor || ICON_COLORS[confirmColor] || ICON_COLORS.warning;

    const actions = (
        <Stack
            direction="row"
            spacing={2}
            sx={{
                width: '100%',
                px: { xs: 2.5, sm: 3 },
                pb: { xs: 2.5, sm: 3 },
                pt: 1,
                borderTop: '1px solid rgba(255, 255, 255, 0.05)',
            }}
        >
            <Button
                fullWidth
                onClick={onClose}
                variant="outlined"
                disabled={loading}
                sx={{
                    color: 'text.secondary',
                    borderColor: 'rgba(255, 255, 255, 0.1)',
                    '&:hover': {
                        borderColor: 'text.secondary',
                        bgcolor: 'rgba(255, 255, 255, 0.05)',
                    },
                }}
            >
                {cancelText}
            </Button>
            <Button
                fullWidth
                onClick={onConfirm}
                variant="contained"
                color={confirmColor}
                disabled={loading}
                startIcon={loading ? <CircularProgress size={18} color="inherit" /> : null}
                sx={{
                    fontWeight: 700,
                    whiteSpace: 'nowrap',
                    ...(confirmColor === 'warning' && {
                        color: '#000',
                    }),
                }}
            >
                {loading ? 'Processing...' : confirmText}
            </Button>
        </Stack>
    );

    return (
        <BaseModal
            open={open}
            onClose={loading ? undefined : onClose}
            title={title}
            maxWidth={maxWidth}
            actions={actions}
        >
            <Box
                sx={{
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    textAlign: 'center',
                    py: { xs: 2, sm: 2.5 },
                    px: 1,
                }}
            >
                <Box
                    sx={{
                        width: 64,
                        height: 64,
                        borderRadius: '50%',
                        bgcolor: alpha(accentColor, 0.12),
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        mb: 2.5,
                    }}
                >
                    <Icon sx={{ color: accentColor, fontSize: 34 }} />
                </Box>

                <Typography
                    variant="body2"
                    sx={{
                        color: 'text.secondary',
                        lineHeight: 1.7,
                        maxWidth: '92%',
                        mx: 'auto',
                        fontSize: '0.925rem',
                    }}
                >
                    {message}
                </Typography>
            </Box>
        </BaseModal>
    );
};

export default ConfirmationModal;
