import dayjs from 'dayjs';
import {
  EXPORT_EMPTY,
  pickMediaUrl,
  formatExerciseInstructions,
  formatExportValue,
} from './exportFormat';

const formatDate = (value, withTime = true, withSeconds = false) => {
  if (!value) return EXPORT_EMPTY;
  const parsed = dayjs(value);
  if (!parsed.isValid()) return EXPORT_EMPTY;
  if (!withTime) return parsed.format('YYYY-MM-DD');
  return parsed.format(withSeconds ? 'YYYY-MM-DD HH:mm:ss' : 'YYYY-MM-DD HH:mm');
};

export const mapExerciseExport = (ex) => {
  const instructions = formatExerciseInstructions(ex.instructions);
  return {
    ID: ex.id,
    Title: ex.title,
    Description: ex.description || EXPORT_EMPTY,
    Category: ex.category,
    Difficulty: ex.difficulty,
    'Muscle Group': ex.target_muscle_group,
    'Thumbnail Image URL': pickMediaUrl(ex, 'thumbnail_url', 'thumbnail', 'image_url', 'image'),
    'Video URL': pickMediaUrl(ex, 'video_url', 'video'),
    'Audio URL': pickMediaUrl(ex, 'audio_url', 'audio'),
    'Duration (seconds)': ex.duration_seconds ?? EXPORT_EMPTY,
    'Rest Time (seconds)': ex.default_rest_time_seconds ?? EXPORT_EMPTY,
    Steps: instructions.steps,
    Dos: instructions.dos,
    Premium: ex.is_premium ? 'Yes' : 'No',
    'Created At': formatDate(ex.created_at),
  };
};

