/** Flatten nested exercise list on a workout for export, if present. */
export const formatWorkoutExercisesMedia = (workout) => {
  const exercises = workout.exercises || workout.workout_exercises;
  if (!Array.isArray(exercises) || exercises.length === 0) return EXPORT_EMPTY;
  return exercises
    .map((ex, i) => {
      const title = ex.title || ex.name || `Exercise ${i + 1}`;
      const thumb = pickMediaUrl(ex, 'thumbnail_url', 'thumbnail');
      const video = pickMediaUrl(ex, 'video_url', 'video');
      const audio = pickMediaUrl(ex, 'audio_url', 'audio');
      return `${title} [thumb: ${thumb}; video: ${video}; audio: ${audio}]`;
    })
    .join(' || ');
};

